# Integration tests for package metadata validation. Run with bash.
set -euo pipefail

root=$(git -C "$(dirname "$0")" rev-parse --show-toplevel)
scripts="${root}/lib/node_modules/@stdlib/_tools/package-json/scripts"
test_dir=$(mktemp -d)
trap 'rm -rf "${test_dir}"' EXIT
export NODE_PATH="${root}/lib/node_modules:${root}/node_modules:${NODE_PATH:-}"

# Check a command's exit status and retain its diagnostics on failure:
expect_status() {
	local expected="$1"
	local status=0
	shift
	"$@" > "${test_dir}/stdout" 2> "${test_dir}/stderr" || status=$?
	if [ "${status}" -ne "${expected}" ]; then
		cat "${test_dir}/stdout" "${test_dir}/stderr" >&2
		echo "Expected exit status ${expected}; received ${status}: $*" >&2
		exit 1
	fi
}

# Exercise the real validator and updaters in a disposable repository:
fixture="${test_dir}/repo"
mkdir -p "${fixture}"
git init -q "${fixture}"
cd "${fixture}"
tools='lib/node_modules/@stdlib/_tools'
mkdir -p "${tools}/package-json/scripts" "${tools}/lint/pkg-json-names/bin"
validator="${fixture}/${tools}/package-json/scripts/validate_package_json_files"
cp "${scripts}/validate_package_json_files" "${validator}"
ln -s "${root}/${tools}/lint/pkg-json-names/bin/cli" "${tools}/lint/pkg-json-names/bin/cli"
for updater in update_directories update_gypfile; do
	ln -s "${scripts}/${updater}" "${tools}/package-json/scripts/${updater}"
done

pkg='lib/node_modules/@stdlib/utils/noop'
other='lib/node_modules/@stdlib/utils/other'
mkdir -p "${pkg}/lib" "${other}/include"
touch "${pkg}/lib/index.js" "${other}/include.gypi"
node - "${pkg}" "${other}" <<'NODE'
var fs = require( 'fs' );
function write( path, pkg ) {
	fs.writeFileSync( path, JSON.stringify( pkg, null, 2 )+'\n' );
}
write( 'package.json', { 'name': '@stdlib/stdlib', 'directories': { 'lib': './lib' } } );
write( process.argv[ 2 ]+'/package.json', { 'name': '@stdlib/utils/noop', 'directories': { 'lib': './lib' } } );
write( process.argv[ 3 ]+'/package.json', { 'name': '@stdlib/utils/other', 'directories': {} } );
write( 'lib/node_modules/@stdlib/utils/package.json', { 'name': '@stdlib/utils', 'directories': {} } );
NODE

expect_status 0 "${validator}" "${pkg}/lib/index.js"
expect_status 0 "${validator}"
expect_status 0 "${validator}" '  '

# Adding and removing package directories or GYP files must fail until fixed:
mkdir "${pkg}/include"
touch "${pkg}/include/example.h" "${pkg}/binding.gyp"
expect_status 1 "${validator}" "${pkg}/include/example.h" "${pkg}/binding.gyp"
node -e 'var p = require(process.argv[1]); if (p.directories.include !== "./include" || p.gypfile !== true) process.exit(1);' "${fixture}/${pkg}/package.json"
expect_status 0 "${validator}" "${pkg}/lib/index.js"
rm -r "${pkg}/include"
rm "${pkg}/binding.gyp"
expect_status 1 "${validator}" "${pkg}/lib/index.js"
node -e 'var p = require(process.argv[1]); if (p.directories.include || p.gypfile) process.exit(1);' "${fixture}/${pkg}/package.json"

# Root and namespace files must not update unrelated descendant manifests:
mkdir "${pkg}/include"
cp "${pkg}/package.json" "${test_dir}/pkg-before.json"
cp "${other}/package.json" "${test_dir}/other-before.json"
expect_status 0 "${validator}" README.md
expect_status 0 "${validator}" lib/node_modules/@stdlib/utils/README.md
cmp "${pkg}/package.json" "${test_dir}/pkg-before.json"
cmp "${other}/package.json" "${test_dir}/other-before.json"

# Existing recursive updater invocations must retain their behavior:
expect_status 0 "${scripts}/update_directories" lib/node_modules/@stdlib/utils
expect_status 0 "${scripts}/update_gypfile" lib/node_modules/@stdlib/utils
node -e 'var p = require(process.argv[1]); if (p.directories.include !== "./include" || p.gypfile !== true) process.exit(1);' "${fixture}/${other}/package.json"

# Each updater failure must reach the caller, even if the manifest is unchanged:
for updater in update_directories update_gypfile; do
	rm "${tools}/package-json/scripts/${updater}"
	printf '#!/usr/bin/env bash\nexit 23\n' > "${tools}/package-json/scripts/${updater}"
	chmod +x "${tools}/package-json/scripts/${updater}"
	expect_status 1 "${validator}" "${pkg}/lib/index.js"
	grep -q 'ERROR: Failed to update' "${test_dir}/stderr"
	rm "${tools}/package-json/scripts/${updater}"
	ln -s "${scripts}/${updater}" "${tools}/package-json/scripts/${updater}"
done

# Package name validation failures must still propagate:
cp "${pkg}/package.json" "${test_dir}/valid.json"
node -e 'var fs = require("fs"); var p = require(process.argv[1]); delete p.name; fs.writeFileSync(process.argv[1], JSON.stringify(p, null, 2)+"\n");' "${fixture}/${pkg}/package.json"
expect_status 1 "${validator}" "${pkg}/package.json"
cp "${test_dir}/valid.json" "${pkg}/package.json"

# Run the actual workflow command through the actual Make recipe:
node - "${root}" "${test_dir}/workflow" <<'NODE'
var fs = require( 'fs' );
var yaml = require( 'js-yaml' );
var workflow = yaml.load( fs.readFileSync( process.argv[ 2 ]+'/.github/workflows/lint_changed_files.yml', 'utf8' ) );
var step = workflow.jobs.lint.steps.filter( function ( step ) {
	return step.name === 'Lint package.json metadata';
})[ 0 ];
if ( step.env.FILES !== '${{ steps.changed-files.outputs.files }}' ) {
	throw new Error( 'Expected changed filenames in the environment.' );
}
fs.writeFileSync( process.argv[ 3 ], step.run );
NODE
printf 'TOOLS_PKGS_DIR := %s\nNODE_MODULES := %s\ninclude %s\n' \
	"${fixture}/${tools}" "${root}/node_modules" "${root}/tools/make/lib/lint/pkgs/Makefile" > Makefile
mkdir "${test_dir}/bin"
# shellcheck disable=SC2016
printf '#!/usr/bin/env bash\nprintf "%%s" "$1"\n' > "${test_dir}/capture"
chmod +x "${test_dir}/capture"
for make_command in make gmake; do
	if ! command -v "${make_command}" > /dev/null; then
		continue
	fi
	make_path=$(command -v "${make_command}")
	printf '#!/usr/bin/env bash\nexec "%s" "$@"\n' "${make_path}" > "${test_dir}/bin/make"
	chmod +x "${test_dir}/bin/make"
	# These expressions are intentionally literal filenames:
	# shellcheck disable=SC2016
	for files in \
		"${pkg}/lib/index.js" \
		'$(touch${IFS}injected).js' \
		'$$(touch${IFS}injected).js' \
		'`touch${IFS}injected`.js' \
		'README.md;touch${IFS}injected;#' \
		'$(shell touch injected).js'; do
		expect_status 0 env PATH="${test_dir}/bin:${PATH}" FILES="${files}" bash -eo pipefail "${test_dir}/workflow"
		test ! -e injected

		# The full Makefile also evaluates shell commands while loading includes:
		full_files="${files//injected/${test_dir}/injected}"
		expect_status 0 "${make_path}" -s -C "${root}" lint-pkgs-metadata-files "FILES=${full_files}" "VALIDATE_PKG_JSON=${test_dir}/capture"
		test ! -e "${test_dir}/injected"
		grep -Fq -- "${full_files}" "${test_dir}/stdout"
	done
done

echo 'Package metadata validation regression tests passed.'
